import type { Manifest } from "./manifest.js";

/** Renders content/clip-lines.md from the manifest so the approval doc never drifts. */
export function renderClipLines(m: Manifest): string {
  const out: string[] = [
    "# Clip lines — for Vitaly's approval",
    "",
    "<!-- generated by `npm run assetgen -- lines --write` from assets/manifest.yaml; edit the manifest, not this file -->",
    "",
    "Every fixed line that will be synthesised (SLNG TTS) before the event. Speaking clips are",
    "lip-synced onto the persona's still; voice samples are only for picking voices.",
    "Live roast lines are not here — those are generated at runtime.",
    "",
  ];
  const speaking = m.assets.filter((e) => e.kind === "clip-speaking");
  const silent = m.assets.filter((e) => e.kind === "clip-silent");
  const voices = m.assets.filter((e) => e.kind === "voice");
  out.push("## Speaking clips", "", "| clip | speaker | ~s | line |", "|---|---|---|---|");
  for (const e of speaking) out.push(`| \`${e.id}\` | ${e.official} | ${e.duration_s} | ${e.line!.replace(/\|/g, "\\|")} |`);
  out.push("", "## Silent clips (no line)", "", "| clip | official | ~s | action |", "|---|---|---|---|");
  for (const e of silent) out.push(`| \`${e.id}\` | ${e.official} | ${e.duration_s} | ${e.category ?? ""} |`);
  out.push("", "## Voice samples (audition lines)", "", "| sample | voice | line |", "|---|---|---|");
  for (const e of voices) out.push(`| \`${e.id}\` | \`${e.voice}\` | ${e.line!.replace(/\|/g, "\\|")} |`);
  out.push("");
  return out.join("\n");
}
